for (i in list) {
    if (i >= m - n - k) {break}
    var list_i = /img/.test(list[i].select("span")[0]) ? list[i].select("span")[0] : list[i].select("a");
    data.push({
        title: String(list_i.text()).replace(book.name, "").replace(/^\s+|\snew/g, ""),
        link: /img/.test(list[i].select("span")[0]) ? "" : `data:;base64,${java.base64Encode(Url("源站：") + list[i].select("a").attr("href"))},{"type":"uaachapter"}`,
        time: /img/.test(list[i].select("span")[0]) ? "" : list[i].select("span").text(),
        vol: /img/.test(list[i].select("span")[0]) ? true : false,
        vip: /币/.test(list[i].select("span")[0]) ? true : false
    });
}
sleep(T1);
cache.delete('uaasxlock');
data;

